  ('CSM:FIRE 787', 'CSM', 'FIRE 787', 'FIRE', '787', 'Emergency Medical Technician: Basic - Refresher', 2, null, true, null, array[]::text[], array['Possession of a valid, current EMT Basic Certificate, or expired no longer than two years.']::text[], array[]::text[], array['FIRE 797']::text[], 'verified', 'course_detail', 'https://catalog.collegeofsanmateo.edu/current/courses/fire-technology/fire-787.php', '2025-2026'),
  ('CSM:FIRE 797', 'CSM', 'FIRE 797', 'FIRE', '797', 'Emergency Medical Technician: Basic', 11, null, true, 'CSU', array[]::text[], array['Must be at least 18 years old prior to the end of the course., Current certification in Basic Life Support (BLS) for the healthcare provider/professional rescuer through the American Heart Association. Admission into the Emergency Medical Technician (EMT) course.']::text[], array['Vaccinations for healthcare workers per California Code of Regulations, Title 8, Section 5199 Aerosol Transmissible Diseases; Appendix E. Plus, additional vaccinations as listed on the Vaccination Recommendations for Healthcare Workers list, which can be found at http://collegeofsanmateo.edu/emt.']::text[], array[]::text[], 'verified', 'course_detail', 'https://catalog.collegeofsanmateo.edu/current/courses/fire-technology/fire-797.php', '2025-2026'),
